```typescript
/**
 * Pediatric Influenza Prevention & Control Clinical Compass™
 * Logic Engine — AAP 2025–2026 Influenza Policy Statement
 *
 * References:
 * 1. AAP Committee on Infectious Diseases. Recommendations for Prevention and
 *    Control of Influenza in Children, 2025–2026. Pediatrics. 2025.
 * 2. CDC ACIP Influenza Vaccine Recommendations 2025–2026.
 * 3. AAP Red Book 2024–2027: Influenza chapter.
 */

export type InfluenzaRiskCategory =
  | "standard"         // healthy child ≥6 months
  | "high_risk";       // chronic disease, immunocompromised, <2 years, pregnant adolescent

export interface InfluenzaPreventionInput {
  ageMonths: number;
  isFirstInfluenzaSeason: boolean;
  hasChronicLungDisease: boolean; // asthma, BPD, CF
  hasChronicHeartDisease: boolean;
  hasImmunosuppression: boolean;
  hasHIV: boolean;
  hasNeurologicDisorder: boolean; // seizures, developmental delay affecting airway
  hasHemoglobinopathy: boolean; // sickle cell
  hasDiabetes: boolean;
  hasChronicKidneyDisease: boolean;
  hasObesity: boolean; // BMI ≥95th %ile
  isPregnantAdolescent: boolean;
  isResidentLongTermCareFacility: boolean;
  hasEggAllergy: boolean;
  eggAllergyType: "hives_only" | "anaphylaxis" | "none";
  isImmunocompromised: boolean;
  hasAsthma: boolean;
  hasWheezing: boolean; // active wheezing (LAIV precaution)
  receivedInfluenzaVaccinePriorSeason: boolean;
  currentSeasonVaccineReceived: boolean;
  antiviralIndicationPresent: boolean;
  influenzaTestPositive: boolean;
  influenzaTestType: "rapid_antigen" | "PCR" | "none";
  symptomsOnsetHours: number; // for antiviral timing
  householdContactHighRisk: boolean;
}

export interface InfluenzaPreventionRecommendation {
  primaryRecommendation: string;
  riskCategory: InfluenzaRiskCategory;
  vaccinationRecommendation: string;
  vaccineType: string;
  dosesRequired: string;
  antiviralRecommendation: string;
  chemoprophylaxisRecommendation: string;
  urgentFlags: string[];
  counselingPoints: string[];
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessInfluenzaPrevention(
  input: InfluenzaPreventionInput
): InfluenzaPreventionRecommendation {
  const urgentFlags: string[] = [];
  const counselingPoints: string[] = [];

  // ─── Risk category ────────────────────────────────────────────────────────
  const isHighRisk =
    input.ageMonths < 24 ||
    input.hasChronicLungDisease ||
    input.hasChronicHeartDisease ||
    input.hasImmunosuppression ||
    input.hasHIV ||
    input.hasNeurologicDisorder ||
    input.hasHemoglobinopathy ||
    input.hasDiabetes ||
    input.hasChronicKidneyDisease ||
    input.hasObesity ||
    input.isPregnantAdolescent ||
    input.isResidentLongTermCareFacility;

  const riskCategory: InfluenzaRiskCategory = isHighRisk ? "high_risk" : "standard";

  // ─── Vaccine type selection ───────────────────────────────────────────────
  let vaccineType: string;
  let vaccinationRec: string;

  const canReceiveLAIV =
    input.ageMonths >= 24 &&
    !input.isImmunocompromised &&
    !input.hasHIV &&
    !input.isPregnantAdolescent &&
    !input.hasAsthma &&
    !input.hasWheezing &&
    !input.hasChronicLungDisease;

  if (input.ageMonths < 6) {
    urgentFlags.push("INFLUENZA VACCINE NOT APPROVED <6 MONTHS: Vaccinate all household contacts and caregivers (cocooning strategy). Ensure mother vaccinated during pregnancy.");
    vaccineType = "Not applicable — cocooning strategy";
    vaccinationRec = "Influenza vaccine NOT approved for infants <6 months. Vaccinate all household contacts and caregivers. Maternal vaccination during pregnancy provides passive protection.";
  } else if (input.eggAllergyType === "anaphylaxis") {
    vaccineType = "ccIIV4 (cell-culture based, egg-free) or RIV4 (recombinant, egg-free)";
    vaccinationRec = "EGG ANAPHYLAXIS: Use egg-free vaccine — ccIIV4 (Flucelvax) or RIV4 (Flublok, ≥18 years). Administer in medical setting with 15-min observation. Epinephrine available.";
  } else if (canReceiveLAIV) {
    vaccineType = "LAIV4 (FluMist) preferred for healthy children 2–17 years OR IIV4";
    vaccinationRec = "LAIV4 (FluMist intranasal) is an acceptable alternative for healthy children 2–17 years. IIV4 (injectable) is equally effective. Patient/family preference acceptable.";
  } else {
    vaccineType = "IIV4 (inactivated influenza vaccine, quadrivalent)";
    vaccinationRec = `IIV4 (injectable) required. LAIV4 contraindicated due to: ${input.isImmunocompromised ? "immunosuppression" : ""} ${input.hasAsthma || input.hasWheezing ? "asthma/wheezing" : ""} ${input.isPregnantAdolescent ? "pregnancy" : ""}.`;
  }

  // ─── Doses required ──────────────────────────────────────────────────────
  let dosesRequired: string;
  if (input.ageMonths < 6) {
    dosesRequired = "Not applicable";
  } else if (input.isFirstInfluenzaSeason && !input.receivedInfluenzaVaccinePriorSeason) {
    dosesRequired = "2 DOSES required (first influenza season): 0.5mL IM × 2, minimum 4 weeks apart. Children 6 months–8 years who have never received influenza vaccine require 2 doses in first season.";
  } else {
    dosesRequired = "1 DOSE annually. Children ≥9 years: always 1 dose. Children 6 months–8 years who received ≥2 prior doses: 1 dose.";
  }

  // ─── Antiviral treatment ──────────────────────────────────────────────────
  let antiviralRec: string;
  if (input.influenzaTestPositive && input.symptomsOnsetHours <= 48) {
    antiviralRec = isHighRisk
      ? `ANTIVIRAL TREATMENT INDICATED (high-risk, symptoms ≤48h): Oseltamivir (Tamiflu) — dose by weight/age. ≥1 year: 30–75mg BID × 5 days. <1 year: 3mg/kg BID × 5 days. Start ASAP — greatest benefit within 48 hours of symptom onset. Do NOT wait for confirmatory test in high-risk patients.`
      : `Antiviral treatment: Oseltamivir recommended for influenza-positive patients with symptoms ≤48 hours. Reduces duration by ~1 day and severity. Consider for all hospitalized patients regardless of symptom onset timing.`;
  } else if (input.influenzaTestPositive && input.symptomsOnsetHours > 48 && isHighRisk) {
    antiviralRec = "HIGH-RISK + SYMPTOMS >48h: Oseltamivir still recommended for high-risk patients even beyond 48 hours — may reduce complications and hospitalization. Benefit diminishes but risk-benefit favors treatment.";
    urgentFlags.push("HIGH-RISK INFLUENZA >48h: Oseltamivir still indicated — reduces hospitalization risk in high-risk patients.");
  } else if (!input.influenzaTestPositive && isHighRisk && input.antiviralIndicationPresent) {
    antiviralRec = "HIGH-RISK PATIENT with influenza-like illness: Do NOT wait for test results — initiate oseltamivir empirically. Rapid antigen tests have low sensitivity (50–70%). PCR preferred for confirmation.";
  } else {
    antiviralRec = "Antiviral treatment not currently indicated. Supportive care (acetaminophen/ibuprofen for fever, hydration). Avoid aspirin (Reye syndrome risk).";
  }

  // ─── Chemoprophylaxis ────────────────────────────────────────────────────
  let chemoprophylaxis: string;
  if (input.householdContactHighRisk && input.influenzaTestPositive) {
    chemoprophylaxis = "POST-EXPOSURE PROPHYLAXIS (PEP): Oseltamivir for high-risk household contacts. Start within 48 hours of exposure. Duration: 10 days. Dose: same as treatment dose once daily.";
    urgentFlags.push("HIGH-RISK HOUSEHOLD CONTACT: Post-exposure prophylaxis with oseltamivir indicated within 48 hours.");
  } else {
    chemoprophylaxis = "Chemoprophylaxis not routinely indicated. Vaccination is the primary prevention strategy. PEP reserved for high-risk unvaccinated contacts within 48 hours of exposure.";
  }

  // ─── Counseling ───────────────────────────────────────────────────────────
  counselingPoints.push(
    "Annual influenza vaccination is the most effective prevention strategy — recommend for all children ≥6 months.",
    "Vaccination timing: ideally by end of October. Vaccinate any time during influenza season.",
    "Avoid aspirin and aspirin-containing products in children with influenza (Reye syndrome risk).",
    "Fever management: acetaminophen or ibuprofen (≥6 months). Ibuprofen NOT for <6 months.",
    "Return precautions: worsening after initial improvement, respiratory distress, persistent fever >5 days, altered mental status.",
    "Cocooning: vaccinate all household contacts of infants <6 months and immunocompromised individuals."
  );

  if (isHighRisk) {
    counselingPoints.push("HIGH-RISK CHILD: Prioritize early vaccination. Do not delay antiviral treatment — initiate empirically if influenza suspected.");
  }

  const primaryRec = urgentFlags.length > 0
    ? urgentFlags[0]
    : `INFLUENZA PREVENTION — ${riskCategory.replace("_", " ").toUpperCase()}. Age ${Math.floor(input.ageMonths / 12)} years ${input.ageMonths % 12} months. ${input.currentSeasonVaccineReceived ? "Current season vaccine: RECEIVED." : "Current season vaccine: NOT YET RECEIVED — vaccinate now."} ${input.influenzaTestPositive ? "Influenza test POSITIVE — antiviral indicated." : ""}`;

  return {
    primaryRecommendation: primaryRec,
    riskCategory,
    vaccinationRecommendation: vaccinationRec,
    vaccineType,
    dosesRequired,
    antiviralRecommendation: antiviralRec,
    chemoprophylaxisRecommendation: chemoprophylaxis,
    urgentFlags,
    counselingPoints,
    evidenceLevel: "A",
    rationale: `Age ${input.ageMonths} months. Risk: ${riskCategory}. Egg allergy: ${input.eggAllergyType}. Immunocompromised: ${input.isImmunocompromised}. Influenza positive: ${input.influenzaTestPositive}. Symptom onset: ${input.symptomsOnsetHours}h. Per AAP 2025–2026 Influenza Policy Statement.`,
    references: [
      { citation: "AAP Committee on Infectious Diseases. Recommendations for Prevention and Control of Influenza in Children, 2025–2026. Pediatrics. 2025.", url: "https://publications.aap.org/pediatrics" },
      { citation: "CDC ACIP. Prevention and Control of Seasonal Influenza with Vaccines: Recommendations of the Advisory Committee on Immunization Practices — United States, 2025–26 Influenza Season. MMWR. 2025.", url: "https://www.cdc.gov/mmwr" },
      { citation: "AAP Red Book 2024–2027: Influenza. American Academy of Pediatrics. 2024.", url: "https://redbook.solutions.aap.org" },
    ],
  };
}
